package com.parcelproof;
import io.jsonwebtoken.*;import io.jsonwebtoken.security.Keys;import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.beans.factory.annotation.*;import org.springframework.context.annotation.*;import org.springframework.security.authentication.*;import org.springframework.security.config.annotation.authentication.configuration.*;import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;import org.springframework.security.config.annotation.web.builders.*;import org.springframework.security.config.http.*;import org.springframework.security.core.userdetails.*;import org.springframework.security.crypto.bcrypt.*;import org.springframework.security.crypto.password.*;import org.springframework.security.web.*;import org.springframework.security.web.authentication.*;import org.springframework.stereotype.*;import org.springframework.web.cors.*;import org.springframework.web.filter.OncePerRequestFilter;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.Key;import java.util.*;
@Service class JwtService{@Value("${jwt.secret}") String secret;@Value("${jwt.expiration}") long exp;Key key(){return Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));}String gen(AppUser u){return Jwts.builder().subject(u.email).claim("role",u.role.name()).issuedAt(new Date()).expiration(new Date(System.currentTimeMillis()+exp)).signWith(key()).compact();}String email(String t){return Jwts.parser().verifyWith((javax.crypto.SecretKey)key()).build().parseSignedClaims(t).getPayload().getSubject();}boolean valid(String t){try{email(t);return true;}catch(Exception e){return false;}}}
@Service class CustomDetails implements UserDetailsService{final UserRepo users;CustomDetails(UserRepo u){users=u;}public UserDetails loadUserByUsername(String e){AppUser u=users.findByEmail(e).orElseThrow();return User.builder().username(u.email).password(u.password).roles(u.role.name()).disabled(u.status==UserStatus.DISABLED).build();}}
@Component class JwtFilter extends OncePerRequestFilter{final JwtService jwt;final CustomDetails details;JwtFilter(JwtService j,CustomDetails d){jwt=j;details=d;}protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")){String t=h.substring(7);if(jwt.valid(t)&&org.springframework.security.core.context.SecurityContextHolder.getContext().getAuthentication()==null){UserDetails ud=details.loadUserByUsername(jwt.email(t));var a=new UsernamePasswordAuthenticationToken(ud,null,ud.getAuthorities());org.springframework.security.core.context.SecurityContextHolder.getContext().setAuthentication(a);}}c.doFilter(r,s);}}
@Configuration @EnableMethodSecurity class SecurityConfig{final JwtFilter filter;@Value("${app.client.url}")String client;SecurityConfig(JwtFilter f){filter=f;}@Bean SecurityFilterChain chain(HttpSecurity http)throws Exception{return http.csrf(x->x.disable()).cors(x->x.configurationSource(cors())).sessionManagement(x->x.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/auth/**","/api/tracking/**","/api/parcels/tracking/**","/swagger-ui/**","/v3/api-docs/**","/").permitAll().anyRequest().authenticated()).addFilterBefore(filter,UsernamePasswordAuthenticationFilter.class).build();}@Bean CorsConfigurationSource cors(){CorsConfiguration c=new CorsConfiguration();c.setAllowedOrigins(List.of(client));c.setAllowedMethods(List.of("GET","POST","PUT","DELETE","OPTIONS"));c.setAllowedHeaders(List.of("*"));c.setAllowCredentials(true);UrlBasedCorsConfigurationSource s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/**",c);return s;}@Bean PasswordEncoder encoder(){return new BCryptPasswordEncoder();}@Bean AuthenticationManager auth(AuthenticationConfiguration c)throws Exception{return c.getAuthenticationManager();}}
